UPDATE public.content_collections SET data = data || '[{"q":{"en":"Are guides available in Arabic?","ar":"هل يتوفر مرشدون يتحدثون العربية؟","ro":"Există ghizi vorbitori de arabă?"},"a":{"en":"You can request a guide language. Availability of specific languages, including Arabic, cannot be promised before confirmation.","ar":"يمكنك طلب لغة المرشد، ولا يمكن ضمان توفر لغات معينة، بما فيها العربية، قبل التأكيد.","ro":"Poți solicita limba ghidului. Disponibilitatea anumitor limbi, inclusiv araba, nu poate fi promisă înainte de confirmare."}},{"q":{"en":"Do you arrange flights?","ar":"هل ترتبون رحلات الطيران؟","ro":"Organizați și zborurile?"},"a":{"en":"Let us know if flight assistance would help. Any flight arrangements would be handled only through appropriately qualified suppliers.","ar":"أخبرنا إذا كانت المساعدة في حجز الطيران مفيدة لك. أي ترتيبات للطيران ستتم فقط عبر مزودين مؤهلين بشكل مناسب.","ro":"Spune-ne dacă ai nevoie de ajutor cu zborurile. Orice aranjament de zbor s-ar face doar prin furnizori calificați corespunzător."}},{"q":{"en":"Do we need a visa?","ar":"هل نحتاج إلى تأشيرة؟","ro":"Avem nevoie de viză?"},"a":{"en":"It depends on your passport nationality, residence status, travel document, itinerary and dates. Visa-free travel for Kuwait and other GCC nationals is not yet in effect. Please check our travel information page and official sources.","ar":"يعتمد ذلك على جنسية جواز السفر ووضع الإقامة ووثيقة السفر وخط السير والتواريخ. السفر دون تأشيرة لمواطني الكويت ودول الخليج الأخرى غير ساري المفعول بعد. يٌرجى مراجعة صفحة معلومات السفر والمصادر الرسمية.","ro":"Depinde de cetățenia pașaportului, statutul de rezidență, documentul de călătorie, itinerariu și date. Călătoria fără viză pentru cetățenii Kuweitului și ai altor state din Golf nu este încă în vigoare. Consultă pagina de informații de călătorie și sursele oficiale."}},{"q":{"en":"When is payment or a deposit required?","ar":"متى يٌطلب الدفع أو العربون؟","ro":"Când se cere plata sau avansul?"},"a":{"en":"No payment is taken on this website. Deposits and payments would only apply after commercial authorisation and a confirmed written offer.","ar":"لا يتم تحصيل أي مبالغ عبر هذا الموقع. تٌطبَّق العربونات والمدفوعات فقط بعد الحصول على التفويض التجاري وعرض مكتوب مؤكد.","ro":"Pe acest site nu se efectuează plăți. Avansul și plățile s-ar aplica doar după autorizarea comercială și o ofertă scrisă confirmată."}},{"q":{"en":"What are the cancellation terms?","ar":"ما شروط الإلغاء؟","ro":"Care sunt condițiile de anulare?"},"a":{"en":"Cancellation terms will be set out only in a confirmed written offer.","ar":"تٌحدَّد شروط الإلغاء فقط في العرض المكتوب المؤكد.","ro":"Condițiile de anulare vor fi precizate doar într-o ofertă scrisă confirmată."}}]'::jsonb WHERE key = 'faq';